class DB{
  constructor(){this.db=null}
  open(){return new Promise((res,rej)=>{const r=indexedDB.open('financasPastel',2);r.onupgradeneeded=e=>{const d=e.target.result;['transactions','accounts','categories','tags','plans','settings','rules'].forEach(s=>{if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:'id'})})};r.onsuccess=()=>{this.db=r.result;res()};r.onerror=()=>rej(r.error)})}
  all(store){return new Promise((res,rej)=>{const r=this.db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
  put(store,obj){return new Promise((res,rej)=>{const r=this.db.transaction(store,'readwrite').objectStore(store).put(obj);r.onsuccess=()=>res(obj);r.onerror=()=>rej(r.error)})}
  del(store,id){return new Promise((res,rej)=>{const r=this.db.transaction(store,'readwrite').objectStore(store).delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
  clear(store){return new Promise((res,rej)=>{const r=this.db.transaction(store,'readwrite').objectStore(store).clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
}
const db=new DB();
const state={tab:'home',date:new Date(),tx:[],accounts:[],categories:[],tags:[],plans:[],rules:[],settings:{pinEnabled:false,pinHash:'',hideValues:false,alert75:true,alert90:true,alertOver:true,notificationsEnabled:false,autoLockMinutes:0,defaultPlan:null,monthlySavingsGoal:null},expandedCat:null,filter:'all',search:'',advFilter:{},analysisFilter:{period:'6m',compare:'previous',accountId:'',categoryId:'',merchant:'',selectedMonths:[]},monthChartPoint:null,modal:null,locked:false};

async function boot(){await db.open();await seed();await load();state.locked=!!(state.settings.pinEnabled&&state.settings.pinHash);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});document.addEventListener('visibilitychange',handleVisibilityLock);render()}
async function seed(){if(!(await db.all('accounts')).length)for(const a of DEFAULT_ACCOUNTS)await db.put('accounts',a);if(!(await db.all('categories')).length)for(const c of [...DEFAULT_CATEGORIES,...INCOME_CATEGORIES])await db.put('categories',c);if(!(await db.all('settings')).length)await db.put('settings',{id:'prefs',...state.settings});}
