function monthBounds(){const y=state.date.getFullYear(),m=state.date.getMonth();const k=`${y}-${String(m+1).padStart(2,'0')}`;return {y,m,k}}
function txForMonth(k=monthBounds().k){return state.tx.filter(t=>monthKey(t.date)===k)}
function cat(id){return state.categories.find(c=>c.id===id)}function acct(id){return state.accounts.find(a=>a.id===id)}
function realExpenses(list){return list.filter(t=>t.type==='expense'&&!t.parentRefundId).reduce((s,t)=>s+t.amount,0)}
function refunds(list){return list.filter(t=>t.type==='refund').reduce((s,t)=>s+t.amount,0)}
function incomes(list){return list.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0)}
