function categoryTotals(list){const out={};for(const t of list){if(t.type==='expense')for(const x of expenseAllocations(t))out[x.categoryId]=(out[x.categoryId]||0)+x.amount;if(t.type==='refund'){const p=state.tx.find(x=>x.id===t.refundOf);if(p){const alloc=expenseAllocations(p),total=alloc.reduce((a,x)=>a+x.amount,0)||p.amount;for(const x of alloc)out[x.categoryId]=(out[x.categoryId]||0)-t.amount*(x.amount/total)}}}return out}
function calcTxSearchText(t){return [t.description,t.merchant,t.subcategory,t.note,(cat(t.categoryId)||{}).name,(acct(t.accountId)||{}).name,acct(t.fromAccountId)?.name,acct(t.toAccountId)?.name,(t.tags||[]).join(' ')].filter(Boolean).join(' ').toLowerCase()}
