function comparisonRange(){const r=analysisRange(),mode=state.analysisFilter.compare||'previous';if(mode==='none'||!r.start||state.analysisFilter.period==='all')return null;const s=new Date(r.start+'T12:00:00'),e=new Date(r.end+'T12:00:00');if(mode==='year'){s.setFullYear(s.getFullYear()-1);e.setFullYear(e.getFullYear()-1);return {start:s.toISOString().slice(0,10),end:e.toISOString().slice(0,10)}}const n=r.months||1,ps=new Date(s.getFullYear(),s.getMonth()-n,1),pe=new Date(s);pe.setDate(0);return {start:ps.toISOString().slice(0,10),end:pe.toISOString().slice(0,10)} }
function analysisFilterRows(rows){const f=state.analysisFilter;return rows.filter(t=>!f.accountId||t.accountId===f.accountId||t.fromAccountId===f.accountId||t.toAccountId===f.accountId).filter(t=>!f.categoryId||t.categoryId===f.categoryId||(t.splits||[]).some(x=>x.categoryId===f.categoryId)||(t.type==='refund'&&state.tx.find(x=>x.id===t.refundOf)?.categoryId===f.categoryId)).filter(t=>!f.merchant||(t.merchant||t.description||'').toLowerCase().includes(f.merchant.toLowerCase()))}
