function rangeLabel(r){if(!r?.start)return 'Todo o histórico';const a=new Date(r.start+'T12:00:00'),b=new Date(r.end+'T12:00:00');const mo=d=>new Intl.DateTimeFormat('pt-PT',{month:'short'}).format(d).replace('.','');if(a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth())return monthName(a.getFullYear(),a.getMonth());if(a.getFullYear()===b.getFullYear())return `${mo(a)}–${mo(b)} ${b.getFullYear()}`;return `${mo(a)} ${a.getFullYear()}–${mo(b)} ${b.getFullYear()}`}
