function monthKeysInRange(r){if(!r?.start||!r?.end)return[];const out=[],s=new Date(r.start+'T12:00:00'),e=new Date(r.end+'T12:00:00');let d=new Date(s.getFullYear(),s.getMonth(),1);while(d<=e&&out.length<240){out.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);d.setMonth(d.getMonth()+1)}return out}
