function analysisLineChart(points){if(!points.length)return '<div class="empty">Ainda não há dados.</div>';const W=620,H=210,pad={l:16,r:16,t:16,b:34},max=Math.max(...points.map(p=>p.value),1),step=(W-pad.l-pad.r)/Math.max(points.length-1,1),xy=points.map((p,i)=>({x:pad.l+i*step,y:pad.t+(H-pad.t-pad.b)*(1-p.value/max),...p})),path=xy.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' '),tickEvery=Math.max(1,Math.ceil(points.length/6));return `<div class="line-chart-wrap"><svg class="line-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolução das despesas"><line x1="${pad.l}" y1="${H-pad.b}" x2="${W-pad.r}" y2="${H-pad.b}" class="chart-axis"/><path d="${path}" class="trend-line" fill="none"/>${xy.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="4" class="trend-dot"><title>${esc(String(p.label))}: ${money(p.value)}</title></circle>${(i%tickEvery===0||i===xy.length-1)?`<text x="${p.x}" y="${H-10}" text-anchor="middle" class="chart-label">${esc(String(p.label))}</text>`:''}`).join('')}</svg></div>`}
function budgetTotalsForRange(r){const keys=monthKeysInRange(r);let budget=0;for(const k of keys){const p=planFor(k);budget+=p.explicitBudget||0}return {budget,keys}}
function recurringMonthlyTotal(){const f=state.analysisFilter;return state.tx.filter(t=>t.type==='expense'&&t.recurring?.enabled).filter(t=>!f.accountId||t.accountId===f.accountId).filter(t=>!f.categoryId||t.categoryId===f.categoryId||(t.splits||[]).some(x=>x.categoryId===f.categoryId)).filter(t=>!f.merchant||(t.merchant||t.description||'').toLowerCase().includes(f.merchant.toLowerCase())).reduce((s,t)=>s+t.amount,0)}
