function categoryEditModal(id,kind='expense'){const c=id?cat(id):null;return modalFrame(c?'Editar categoria':'Nova categoria',`<form id="category-form" class="form-grid"><input type="hidden" name="id" value="${c?.id||''}"><input type="hidden" name="type" value="${c?.type||kind}"><div class="inline-grid"><div class="field"><label>Emoji</label><input class="input" name="emoji" value="${esc(c?.emoji||'✨')}" maxlength="4"></div><div class="field"><label>Nome</label><input class="input" name="name" value="${esc(c?.name||'')}" required></div></div><div class="field"><label>Cor pastel</label><select class="select" name="color">${[['#f4eef5','Lilás'],['#e6f6ef','Menta'],['#fdebed','Rosa'],['#fff0df','Pêssego'],['#eaf3fb','Azul'],['#fff7d8','Amarelo']].map(([v,l])=>`<option value="${v}" ${c?.color===v?'selected':''}>${l}</option>`).join('')}</select></div><button class="save-btn" type="submit">Guardar categoria</button>${c?`<button type="button" class="secondary-btn danger-btn" data-action="archive-category" data-id="${c.id}">Arquivar categoria</button>`:''}</form>`)}
function rulesModal(){return modalFrame('Regras automáticas',`<div class="section-title"><h2>Regras</h2><button class="text-btn" data-action="new-rule">＋ Nova</button></div><div class="card">${state.rules.length?state.rules.map(r=>`<button class="row" style="width:100%;border-left:0;border-right:0;border-top:0;background:transparent;text-align:left" data-action="edit-rule" data-id="${r.id}"><span class="cat-icon" style="background:var(--butter)">⚡</span><span class="row-main"><span class="row-title">Contém “${esc(r.match)}”</span><span class="row-sub">${cat(r.categoryId)?.name||'Sem categoria'} · ${acct(r.accountId)?.name||'Sem conta'}</span></span><span>›</span></button>`).join(''):'<div class="empty">Ainda não tens regras automáticas.</div>'}</div>`)}
function ruleEditModal(id,sourceTxId){const r=id?state.rules.find(x=>x.id===id):null,t=sourceTxId?state.tx.find(x=>x.id===sourceTxId):null;return modalFrame(r?'Editar regra':'Nova regra',`<form id="rule-form" class="form-grid"><input type="hidden" name="id" value="${r?.id||''}"><div class="field"><label>Quando a descrição contém</label><input class="input" name="match" value="${esc(r?.match||t?.merchant||t?.description||'')}" required></div><div class="field"><label>Nome Loja/Empresa (opcional)</label><input class="input" name="merchant" value="${esc(r?.merchant||t?.merchant||'')}"></div><div class="field"><label>Categoria</label><select class="select" name="categoryId"><option value="">Não alterar</option>${state.categories.filter(c=>c.type==='expense'&&!c.archived).map(c=>`<option value="${c.id}" ${(r?.categoryId||t?.categoryId)===c.id?'selected':''}>${c.emoji} ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Conta</label><select class="select" name="accountId"><option value="">Não alterar</option>${state.accounts.map(a=>`<option value="${a.id}" ${(r?.accountId||t?.accountId)===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><button class="save-btn" type="submit">Guardar regra</button>${r?`<button type="button" class="secondary-btn danger-btn" data-action="delete-rule" data-id="${r.id}">Apagar regra</button>`:''}</form>`)}
function summaryModal(k){
  const s=monthStats(k),[y,m]=k.split('-').map(Number),prev=new Date(y,m-2,1),prevK=`${prev.getFullYear()}-${String(prev.getMonth()+1).padStart(2,'0')}`,ps=monthStats(prevK);
  const currentTotals=categoryTotals(s.list),prevTotals=categoryTotals(ps.list),allIds=[...new Set([...Object.keys(currentTotals),...Object.keys(prevTotals)])];
  const cats=Object.entries(currentTotals).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]),top=cats[0];
  const comparison=allIds.map(id=>{const current=Math.max(0,currentTotals[id]||0),previous=Math.max(0,prevTotals[id]||0),delta=current-previous,pct=previous>0?delta/previous*100:null;return{id,current,previous,delta,pct}}).filter(x=>x.current>0||x.previous>0).sort((a,b)=>b.current-a.current||Math.abs(b.delta)-Math.abs(a.delta));
  const expenseRows=s.list.filter(t=>t.type==='expense'),monthTotal=Math.max(0,s.exp),dayPatternsAllowed=k>='2026-09';
  const patterns=cats.slice(0,4).map(([id,value])=>{
    const allocations=expenseRows.flatMap(t=>expenseAllocations(t).filter(a=>a.categoryId===id).map(a=>({t,amount:a.amount}))),count=new Set(allocations.map(x=>x.t.id)).size,share=monthTotal>0?value/monthTotal*100:0;
    let timing='';
    if(dayPatternsAllowed&&allocations.length){const weekend=allocations.filter(x=>[0,6].includes(new Date(x.t.date+'T12:00:00').getDay())).reduce((sum,x)=>sum+x.amount,0),weekendShare=value>0?weekend/value*100:0;if(weekendShare>=65)timing=` · ${weekendShare.toFixed(0)}% ao fim de semana`;else if(weekendShare<=35)timing=` · ${(100-weekendShare).toFixed(0)}% em dias úteis`;}
    return {id,value,count,share,timing};
  });
  return modalFrame(`${monthName(y,m-1)} em resumo`,`<div class="card hero"><div class="eyebrow">🌸 Resumo mensal</div><div class="hero-value">${money(s.savings)} poupados</div><div class="hero-sub">${s.savingsGoal?`Objetivo mensal ${money(s.savingsGoal)} · ${s.savings>=s.savingsGoal?'atingido':'não atingido'}`:'Sem objetivo mensal definido'}</div></div><div class="hero-grid">${metric('Receitas',money(s.inc),'mint')}${metric('Despesas líquidas',money(s.exp),'pink')}${metric('Reembolsos',money(s.ref),'peach')}${metric('Maior categoria',top?cat(top[0])?.name||'—':'—','lilac')}</div><section class="section month-deep-dive"><div class="section-title"><h2>Deep-dive do mês</h2></div><div class="card deep-dive-card"><div class="deep-dive-subtitle">Comparação por categoria</div>${comparison.map(x=>{const c=cat(x.id),change=x.previous===0?(x.current>0?'Nova este mês':'—'):`${x.delta>=0?'+':''}${x.pct.toFixed(0)}%`;return `<div class="deep-category-row"><span class="cat-icon" style="background:${c?.color||'#eee'}">${c?.emoji||'•'}</span><span class="deep-category-main"><b>${esc(c?.name||'Categoria')}</b><small>${money(x.current)} este mês · ${money(x.previous)} no mês anterior</small></span><span class="deep-category-change ${x.delta<=0?'positive':'negative'}">${esc(change)}</span></div>`}).join('')||'<div class="empty">Sem categorias para comparar.</div>'}</div><div class="card deep-dive-card"><div class="deep-dive-subtitle">Padrões por categoria</div>${patterns.map(x=>{const c=cat(x.id);return `<div class="deep-pattern-row"><span>${c?.emoji||'•'}</span><div><b>${esc(c?.name||'Categoria')}</b><small>${x.share.toFixed(0)}% das despesas · ${x.count} ${x.count===1?'movimento':'movimentos'}${x.timing}</small></div></div>`}).join('')||'<div class="empty">Sem dados suficientes para encontrar padrões.</div>'}</div></section>`)
}
function pinSetupModal(){return modalFrame('Definir PIN',`<form id="pin-form" class="form-grid"><div class="field"><label>Novo PIN (4–8 dígitos)</label><input class="input" name="pin" type="password" inputmode="numeric" minlength="4" maxlength="8" pattern="[0-9]{4,8}" required></div><div class="field"><label>Confirmar PIN</label><input class="input" name="confirm" type="password" inputmode="numeric" minlength="4" maxlength="8" required></div><button class="save-btn" type="submit">Guardar PIN</button></form>`)}

function analysisMonthDetailModal(k){const rows=analysisFilterRows(state.tx.filter(t=>monthKey(t.date)===k)),income=incomes(rows),expense=netExpenses(rows),saving=income-expense;return modalFrame(monthLabelKey(k),`<div class="analysis-month-modal"><div class="analysis-month-modal-grid"><div><span>Rendimentos</span><b class="income-cell">${money(income)}</b></div><div><span>Despesas</span><b class="expense-cell">${money(expense)}</b></div><div><span>Poupança</span><b class="saving-cell ${saving<0?'negative':''}">${money(saving)}</b></div></div><div class="tiny analysis-month-count">${rows.length} ${rows.length===1?'movimento':'movimentos'} com os filtros atuais</div><button type="button" class="save-btn" data-action="analysis-go-month" data-month="${k}">Ver detalhe do mês →</button></div>`)}

function monthPickerModal(year){const selectedYear=Number.isInteger(year)?year:state.date.getFullYear(),selectedMonth=state.date.getMonth(),months=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'],now=new Date(),isCurrentYear=selectedYear===now.getFullYear();return modalFrame('Escolher mês',`<div class="month-picker"><div class="year-picker"><button type="button" class="icon-btn" data-action="month-picker-year-prev" aria-label="Ano anterior">‹</button><div class="year-value">${selectedYear}</div><button type="button" class="icon-btn" data-action="month-picker-year-next" aria-label="Ano seguinte">›</button></div><div class="month-grid">${months.map((name,i)=>`<button type="button" class="month-choice ${selectedYear===state.date.getFullYear()&&i===selectedMonth?'selected':''} ${isCurrentYear&&i===now.getMonth()?'current':''}" data-action="choose-month" data-year="${selectedYear}" data-month="${i}">${name}</button>`).join('')}</div><button type="button" class="secondary-btn month-today-btn" data-action="go-today">Ir para hoje</button></div>`)}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});document.querySelectorAll('[data-action]').forEach(b=>{const a=b.dataset.action;if(a==='open-add')b.onclick=()=>{state.modal={type:'add',kind:'expense'};render()};if(a==='prev-month')b.onclick=()=>{state.date=new Date(state.date.getFullYear(),state.date.getMonth()-1,1);render()};if(a==='next-month')b.onclick=()=>{state.date=new Date(state.date.getFullYear(),state.date.getMonth()+1,1);render()};if(a==='pick-month')b.onclick=()=>{state.modal={type:'month-picker',year:state.date.getFullYear()};render()};if(a==='month-picker-year-prev')b.onclick=()=>{state.modal={type:'month-picker',year:(state.modal?.year??state.date.getFullYear())-1};render()};if(a==='month-picker-year-next')b.onclick=()=>{state.modal={type:'month-picker',year:(state.modal?.year??state.date.getFullYear())+1};render()};if(a==='choose-month')b.onclick=()=>{state.date=new Date(Number(b.dataset.year),Number(b.dataset.month),1);state.modal=null;render()};if(a==='go-today')b.onclick=()=>{const d=new Date();state.date=new Date(d.getFullYear(),d.getMonth(),1);state.modal=null;render()};if(a==='go-month')b.onclick=()=>{state.tab='month';render()};if(a==='go-analysis')b.onclick=()=>{state.tab='analysis';render()};if(a==='analysis-month-detail')b.onclick=()=>{state.modal={type:'analysis-month',k:b.dataset.month};render()};if(a==='analysis-go-month')b.onclick=()=>{const [y,m]=b.dataset.month.split('-').map(Number);state.date=new Date(y,m-1,1);state.modal=null;state.tab='month';render()};if(a==='analysis-select-all')b.onclick=()=>{state.analysisFilter.period='all';state.analysisFilter.selectedMonths=[];render()};if(a==='month-chart-point')b.onclick=()=>{state.monthChartPoint={day:Number(b.dataset.day),value:Number(b.dataset.value),y:Number(b.dataset.year),m:Number(b.dataset.month)};render()};if(a==='toggle-cat')b.onclick=()=>{state.expandedCat=state.expandedCat===b.dataset.id?null:b.dataset.id;render()};if(a==='go-month-movements')b.onclick=()=>{state.tab='movements';state.search='';render()};if(a==='tx-detail')b.onclick=()=>{state.modal={type:'tx',id:b.dataset.id};render()};if(a==='close-modal')b.onclick=()=>{state.modal=null;render()};if(a==='switch-kind')b.onclick=()=>{state.modal={type:'add',kind:b.dataset.kind};render()};if(a==='toggle-more')b.onclick=()=>document.getElementById('more-fields')?.classList.toggle('hidden');if(a==='delete-tx')b.onclick=async()=>{if(confirm('Apagar este movimento?')){await db.del('transactions',b.dataset.id);state.modal=null;await load();render();toast('Movimento apagado')}};if(a==='refund')b.onclick=()=>{state.modal={type:'refund',id:b.dataset.id};render()};if(a==='edit-tx')b.onclick=()=>{state.modal={type:'edit',id:b.dataset.id};render()};if(a==='split')b.onclick=()=>{state.modal={type:'split',id:b.dataset.id};render()};if(a==='add-split-row')b.onclick=()=>document.getElementById('split-rows')?.insertAdjacentHTML('beforeend',splitRowHtml({},Date.now()));if(a==='edit-plan'||a==='plan')b.onclick=()=>{state.modal={type:'plan'};render()};if(a==='settings')b.onclick=()=>{state.modal={type:'settings'};render()};if(a==='backup')b.onclick=()=>{state.modal={type:'backup'};render()};if(a==='account-detail')b.onclick=()=>{state.modal={type:'account',id:b.dataset.id};render()};if(a==='new-account')b.onclick=()=>{state.modal={type:'account-edit'};render()};if(a==='edit-account')b.onclick=()=>{state.modal={type:'account-edit',id:b.dataset.id};render()};if(a==='archive-account')b.onclick=()=>archiveAccount(b.dataset.id);if(a==='categories')b.onclick=()=>{state.modal={type:'categories'};render()};if(a==='new-category')b.onclick=()=>{state.modal={type:'category-edit',kind:b.dataset.kind};render()};if(a==='edit-category')b.onclick=()=>{state.modal={type:'category-edit',id:b.dataset.id};render()};if(a==='archive-category')b.onclick=()=>archiveCategory(b.dataset.id);if(a==='advanced-filters')b.onclick=()=>{state.modal={type:'filters'};render()};if(a==='clear-filters')b.onclick=()=>{state.advFilter={};render()};if(a==='rules')b.onclick=()=>{state.modal={type:'rules'};render()};if(a==='new-rule')b.onclick=()=>{state.modal={type:'rule-edit'};render()};if(a==='edit-rule')b.onclick=()=>{state.modal={type:'rule-edit',id:b.dataset.id};render()};if(a==='new-rule-from-tx')b.onclick=()=>{state.modal={type:'rule-edit',sourceTxId:b.dataset.id};render()};if(a==='delete-rule')b.onclick=()=>deleteRule(b.dataset.id);if(a==='confirm-recurring')b.onclick=()=>confirmRecurring(b.dataset.id,b.dataset.date);if(a==='open-summary')b.onclick=()=>{state.modal={type:'summary',k:monthBounds().k};render()};if(a==='change-pin')b.onclick=()=>{state.modal={type:'pin-setup'};render()};if(a==='lock-now')b.onclick=()=>{state.modal=null;state.locked=true;render()};if(a==='download-backup')b.onclick=downloadBackup;if(a==='export-csv')b.onclick=exportCSV;if(a==='wipe')b.onclick=wipe});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});const search=document.getElementById('search');if(search)search.oninput=e=>{state.search=e.target.value;setTimeout(render,0)};const desc=document.querySelector('#tx-form input[name="description"]');if(desc)desc.onblur=()=>applyRuleToForm(desc.value);const txf=document.getElementById('tx-form');if(txf){txf.onsubmit=saveTx;const from=txf.querySelector('select[name="fromAccountId"]'),to=txf.querySelector('select[name="toAccountId"]');if(from&&to){const keepDifferent=changed=>{if(from.value===to.value&&state.accounts.length>1){const other=state.accounts.find(a=>a.id!==changed.value);if(other)(changed===from?to:from).value=other.id}};from.onchange=()=>keepDifferent(from);to.onchange=()=>keepDifferent(to)}};const edit=document.getElementById('edit-tx-form');if(edit)edit.onsubmit=saveEditedTx;const rf=document.getElementById('refund-form');if(rf)rf.onsubmit=saveRefund;const sf=document.getElementById('split-form');if(sf)sf.onsubmit=saveSplit;const pf=document.getElementById('plan-form');if(pf)pf.onsubmit=savePlan;const ff=document.getElementById('filters-form');if(ff)ff.onsubmit=saveFilters;const af=document.getElementById('account-form');if(af)af.onsubmit=saveAccount;const cf=document.getElementById('category-form');if(cf)cf.onsubmit=saveCategory;const rulef=document.getElementById('rule-form');if(rulef)rulef.onsubmit=saveRule;const pinf=document.getElementById('pin-form');if(pinf)pinf.onsubmit=savePin;const unlock=document.getElementById('unlock-form');if(unlock)unlock.onsubmit=unlockApp;const pin=document.getElementById('pin-toggle');if(pin)pin.onchange=()=>togglePin(pin.checked);const hide=document.getElementById('hide-toggle');if(hide)hide.onchange=()=>saveSetting('hideValues',hide.checked);const autoLock=document.getElementById('auto-lock-select');if(autoLock)autoLock.onchange=()=>saveSetting('autoLockMinutes',Number(autoLock.value));const notif=document.getElementById('notifications-toggle');if(notif)notif.onchange=()=>toggleNotifications(notif.checked);document.querySelectorAll('.setting-toggle').forEach(x=>x.onchange=()=>saveSetting(x.dataset.key,x.checked));const file=document.getElementById('restore-file');if(file)file.onchange=restoreBackup;document.querySelectorAll('[data-analysis-period]').forEach(b=>b.onclick=()=>{state.analysisFilter.period=b.dataset.analysisPeriod;if(state.analysisFilter.period==='custom'&&!(state.analysisFilter.selectedMonths||[]).length)state.analysisFilter.selectedMonths=analysisAvailableMonths();render()});document.querySelectorAll('[data-analysis-month]').forEach(b=>b.onclick=()=>{const k=b.dataset.analysisMonth,cur=new Set(state.analysisFilter.selectedMonths||[]);cur.has(k)?cur.delete(k):cur.add(k);state.analysisFilter.selectedMonths=[...cur].sort();state.analysisFilter.period='custom';render()});document.querySelectorAll('[data-analysis-year]').forEach(b=>b.onclick=()=>{const y=b.dataset.analysisYear,avail=analysisAvailableMonths().filter(k=>k.startsWith(y+'-')),cur=new Set(state.analysisFilter.selectedMonths||[]),all=avail.every(k=>cur.has(k));avail.forEach(k=>all?cur.delete(k):cur.add(k));state.analysisFilter.selectedMonths=[...cur].sort();state.analysisFilter.period='custom';render()});['analysis-account','analysis-category'].forEach(id=>{const el=document.getElementById(id);if(el)el.onchange=()=>{state.analysisFilter[id==='analysis-account'?'accountId':'categoryId']=el.value;render()}});const cmp=document.getElementById('analysis-compare');if(cmp)cmp.onchange=()=>{state.analysisFilter.compare=cmp.value;render()};const am=document.getElementById('analysis-merchant');if(am)am.onchange=()=>{state.analysisFilter.merchant=am.value;render()}}
function renderBase(){let html='';if(state.tab==='home')html=renderHome();if(state.tab==='month')html=renderMonth();if(state.tab==='movements')html=renderMovements();if(state.tab==='analysis')html=renderAnalysis();if(state.tab==='more')html=renderMore();return html}
function parseAmount(v){return Number(String(v).replace(',','.'))||0}
async function saveTx(e){e.preventDefault();const f=new FormData(e.target),kind=f.get('kind'),amount=parseAmount(f.get('amount'));if(!amount)return toast('Indica um valor.');let obj={id:uid(),type:kind,amount,date:f.get('date'),description:f.get('description')||'',createdAt:Date.now()};if(kind==='transfer'){if(f.get('fromAccountId')===f.get('toAccountId'))return toast('Escolhe contas diferentes.');Object.assign(obj,{fromAccountId:f.get('fromAccountId'),toAccountId:f.get('toAccountId')})}else{const tagNames=(f.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean);Object.assign(obj,{categoryId:f.get('categoryId'),accountId:f.get('accountId'),merchant:f.get('merchant')||'',subcategory:f.get('subcategory')||'',note:f.get('note')||'',tags:tagNames,recurring:{enabled:f.get('recurring')==='on',frequency:f.get('recurringFrequency')||'mensal',nextDate:f.get('recurringNextDate')||null}});for(const name of tagNames){if(!state.tags.some(t=>t.name.toLowerCase()===name.toLowerCase()))await db.put('tags',{id:uid(),name})}}await db.put('transactions',obj);const again=e.submitter?.dataset?.saveAnother==='1';state.modal=again?{type:'add',kind}:null;await load();render();toast('Movimento guardado');maybeNotifyBudget(obj.date.slice(0,7))}
async function saveRefund(e){e.preventDefault();const f=new FormData(e.target),orig=state.tx.find(t=>t.id===f.get('refundOf')),amount=parseAmount(f.get('amount'));if(!orig||!amount)return;const prior=state.tx.filter(t=>t.type==='refund'&&t.refundOf===orig.id).reduce((s,t)=>s+t.amount,0);if(prior+amount>orig.amount)return toast('O total reembolsado não pode ultrapassar a despesa original.');await db.put('transactions',{id:uid(),type:'refund',refundOf:orig.id,amount,date:f.get('date'),description:`Reembolso — ${orig.description}`,accountId:f.get('accountId'),note:f.get('note')||'',createdAt:Date.now()});state.modal=null;await load();render();toast('Reembolso registado')}
async function savePlan(e){e.preventDefault();const f=new FormData(e.target),{k}=monthBounds(),categoryBudgets={};document.querySelectorAll('.category-budget-input').forEach(x=>{const v=parseAmount(x.value);if(v>0)categoryBudgets[x.dataset.categoryId]=v});const plan={id:k,expectedIncome:0,savingsGoal:f.get('savingsGoal')?parseAmount(f.get('savingsGoal')):0,explicitBudget:f.get('explicitBudget')?parseAmount(f.get('explicitBudget')):null,categoryBudgets};await db.put('plans',plan);state.modal=null;await load();render();toast('Plano mensal guardado')}
function applyRuleToForm(text){let r=activeRuleFor(text),source=null;if(!r){const q=(text||'').trim().toLowerCase();source=[...state.tx].filter(t=>t.type==='expense'&&((t.description||'').toLowerCase()===q||(t.merchant||'').toLowerCase()===q)).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0))[0]}const form=document.getElementById('tx-form');if(!form)return;if(r){if(r.categoryId&&form.elements.categoryId)form.elements.categoryId.value=r.categoryId;if(r.accountId&&form.elements.accountId)form.elements.accountId.value=r.accountId;if(r.merchant&&form.elements.merchant)form.elements.merchant.value=r.merchant;toast('Sugestão aplicada pela tua regra ⚡')}else if(source){if(source.categoryId&&form.elements.categoryId)form.elements.categoryId.value=source.categoryId;if(source.accountId&&form.elements.accountId)form.elements.accountId.value=source.accountId;if(source.merchant&&form.elements.merchant)form.elements.merchant.value=source.merchant;toast('Sugeri categoria e conta com base no histórico')}}
async function saveEditedTx(e){e.preventDefault();const f=new FormData(e.target),id=f.get('id'),old=state.tx.find(x=>x.id===id);if(!old)return;const kind=f.get('kind'),amount=parseAmount(f.get('amount'));if(!amount)return toast('Indica um valor.');let obj={...old,amount,date:f.get('date'),description:f.get('description')||old.description,updatedAt:Date.now()};if(kind==='transfer'){if(f.get('fromAccountId')===f.get('toAccountId'))return toast('Escolhe contas diferentes.');Object.assign(obj,{fromAccountId:f.get('fromAccountId'),toAccountId:f.get('toAccountId')})}else{Object.assign(obj,{categoryId:f.get('categoryId'),accountId:f.get('accountId'),merchant:f.get('merchant')||'',subcategory:f.get('subcategory')||'',note:f.get('note')||'',tags:(f.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),recurring:kind==='expense'?{enabled:f.get('recurring')==='on',frequency:f.get('recurringFrequency')||'mensal',nextDate:f.get('recurringNextDate')||null}:old.recurring});if(obj.splits?.length){const total=obj.splits.reduce((s,x)=>s+Number(x.amount||0),0);if(Math.abs(total-amount)>.009)obj.splits=null}}await db.put('transactions',obj);state.modal=null;await load();render();toast('Movimento atualizado')}
async function saveSplit(e){e.preventDefault();const f=new FormData(e.target),id=f.get('id'),t=state.tx.find(x=>x.id===id);if(!t)return;const cats=[...document.querySelectorAll('.split-category')],amts=[...document.querySelectorAll('.split-amount')],splits=[];for(let i=0;i<cats.length;i++){const amount=parseAmount(amts[i].value);if(amount>0)splits.push({categoryId:cats[i].value,amount})}const total=splits.reduce((s,x)=>s+x.amount,0);if(Math.abs(total-t.amount)>.009)return toast(`As partes somam ${money(total)}; devem somar ${money(t.amount)}.`);t.splits=splits;t.categoryId=splits[0]?.categoryId||t.categoryId;await db.put('transactions',t);state.modal=null;await load();render();toast('Despesa dividida')}
function saveFilters(e){e.preventDefault();const f=new FormData(e.target);state.advFilter=Object.fromEntries([...f.entries()].filter(([,v])=>v!==''));state.modal=null;render()}
async function saveAccount(e){e.preventDefault();const f=new FormData(e.target),id=f.get('id')||uid();await db.put('accounts',{id,name:f.get('name').trim(),emoji:f.get('emoji')||'💳',monthlyGoal:f.get('monthlyGoal')?parseAmount(f.get('monthlyGoal')):null});state.modal=null;await load();render();toast('Conta guardada')}
async function archiveAccount(id){if(state.tx.some(t=>t.accountId===id||t.fromAccountId===id||t.toAccountId===id))return toast('Esta conta tem movimentos. Mantém-na para preservar o histórico.');if(confirm('Remover esta conta?')){await db.del('accounts',id);state.modal=null;await load();render();toast('Conta removida')}}
async function saveCategory(e){e.preventDefault();const f=new FormData(e.target),id=f.get('id')||uid();await db.put('categories',{id,name:f.get('name').trim(),emoji:f.get('emoji')||'✨',color:f.get('color')||'#f4eef5',type:f.get('type')||'expense',archived:false});state.modal={type:'categories'};await load();render();toast('Categoria guardada')}
async function archiveCategory(id){const c=cat(id);if(!c)return;if(confirm(`Arquivar ${c.name}? Os movimentos antigos mantêm a categoria.`)){await db.put('categories',{...c,archived:true});state.modal={type:'categories'};await load();render();toast('Categoria arquivada')}}
async function saveRule(e){e.preventDefault();const f=new FormData(e.target),id=f.get('id')||uid();await db.put('rules',{id,match:f.get('match').trim(),merchant:f.get('merchant')||'',categoryId:f.get('categoryId')||'',accountId:f.get('accountId')||'',enabled:true});state.modal={type:'rules'};await load();render();toast('Regra guardada')}
async function deleteRule(id){if(confirm('Apagar esta regra?')){await db.del('rules',id);state.modal={type:'rules'};await load();render();toast('Regra apagada')}}
async function confirmRecurring(id,date){const src=state.tx.find(x=>x.id===id);if(!src)return;const clone={...src,id:uid(),date,recurring:{enabled:false},generatedFrom:id,createdAt:Date.now()};await db.put('transactions',clone);src.recurring={...src.recurring,nextDate:addMonths(date,1)};await db.put('transactions',src);await load();render();toast('Movimento recorrente confirmado');maybeNotifyBudget(date.slice(0,7))}
let hiddenAt=0;function handleVisibilityLock(){if(document.hidden){hiddenAt=Date.now();return}const mins=Number(state.settings.autoLockMinutes||0);if(state.settings.pinEnabled&&mins&&hiddenAt&&Date.now()-hiddenAt>=mins*60000){state.modal=null;state.locked=true;render()}hiddenAt=0}
async function togglePin(enabled){if(enabled){state.modal={type:'pin-setup'};render()}else{if(confirm('Desativar o PIN?')){state.settings.pinEnabled=false;state.settings.pinHash='';await db.put('settings',{id:'prefs',...state.settings});render();toast('PIN desativado')}else render()}}
async function savePin(e){e.preventDefault();const f=new FormData(e.target),a=f.get('pin'),b=f.get('confirm');if(a!==b)return toast('Os PINs não coincidem.');if(!/^\d{4,8}$/.test(a))return toast('Usa 4 a 8 dígitos.');state.settings.pinHash=await hashText(a);state.settings.pinEnabled=true;await db.put('settings',{id:'prefs',...state.settings});state.modal=null;render();toast('PIN ativado')}
async function unlockApp(e){e.preventDefault();const f=new FormData(e.target),h=await hashText(f.get('pin'));if(h!==state.settings.pinHash)return toast('PIN incorreto.');state.locked=false;render()}
async function toggleNotifications(enabled){if(enabled){if(!('Notification'in window))return toast('Notificações não suportadas neste dispositivo.');const perm=await Notification.requestPermission();enabled=perm==='granted';if(!enabled)toast('Permissão de notificações não concedida.')}state.settings.notificationsEnabled=enabled;await db.put('settings',{id:'prefs',...state.settings});render()}
async function maybeNotifyBudget(k=monthBounds().k){if(!state.settings.notificationsEnabled||!('Notification'in window)||Notification.permission!=='granted')return;const s=monthStats(k),pct=s.budget?s.exp/s.budget*100:0;let msg='';if(pct>=100&&state.settings.alertOver)msg=`Ultrapassaste o limite do mês. Poupança atual: ${money(s.savings)}.`;else if(pct>=90&&state.settings.alert90)msg=`Já utilizaste ${Math.round(pct)}% do orçamento mensal.`;else if(pct>=75&&state.settings.alert75)msg=`Já utilizaste ${Math.round(pct)}% do orçamento mensal.`;if(!msg)return;try{if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.ready;await reg.showNotification('Finanças Pessoais',{body:msg,icon:'icons/icon-192.png'})}else new Notification('Finanças Pessoais',{body:msg})}catch{}}
async function saveSetting(k,v){state.settings[k]=v;await db.put('settings',{id:'prefs',...state.settings});render();toast('Definição guardada')}
async function downloadBackup(){const data={version:1,exportedAt:new Date().toISOString(),transactions:state.tx,accounts:state.accounts,categories:state.categories,tags:state.tags,plans:state.plans,rules:state.rules,settings:state.settings};downloadBlob(JSON.stringify(data,null,2),'financas-pessoais-backup.json','application/json')}
function exportCSV(){const head=['Data','Tipo','Descrição','Valor','Categoria','Conta','Loja/Empresa','Tags','Nota'];const rows=state.tx.map(t=>[t.date,t.type,t.description,t.amount,cat(t.categoryId)?.name||'',acct(t.accountId)?.name||'',t.merchant||'',(t.tags||[]).join('|'),t.note||'']);const csv=[head,...rows].map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\n');downloadBlob('\ufeff'+csv,'movimentos.csv','text/csv;charset=utf-8')}
function downloadBlob(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function restoreBackup(e){const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());for(const s of ['transactions','accounts','categories','tags','plans','rules']){await db.clear(s);for(const item of (data[s]||[]))await db.put(s,item)}if(data.settings)await db.put('settings',{id:'prefs',...data.settings});await load();state.modal=null;render();toast('Backup restaurado')}catch{toast('Backup inválido')}}
async function wipe(){if(confirm('Apagar todos os movimentos? Esta ação não pode ser anulada.')){await db.clear('transactions');await load();state.modal=null;render();toast('Movimentos apagados')}}
boot();
